import{publishSessionEvents}from"#execution/publish-session-events.js";import{withSessionStateDelta}from"#execution/session/step-state-delta.js";import{settleControl}from"#harness/session-machine/deliveries.js";async function settleControlDeliveryStep(e){"use step";return await withSessionStateDelta(e,t=>publishSessionEvents(t,[settleControl(e.settlement)]))}export{settleControlDeliveryStep};